package com.nigson.experience.consent;

import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.http.*;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;
import tools.jackson.databind.JsonNode;
import com.nigson.shared.observability.WireContext;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.PrivateWorkload;

@RestController
public final class ConsentController {
 private final NewsletterService newsletter;private final org.springframework.beans.factory.ObjectProvider<PhoneConsent> phone;
 public ConsentController(NewsletterService newsletter,org.springframework.beans.factory.ObjectProvider<PhoneConsent> phone){this.newsletter=newsletter;this.phone=phone;}
 private static UUID correlation(){return WireContext.current()==null?WireContext.correlation(null):WireContext.current().correlationId;}
 private static String key(HttpServletRequest request){var values=Collections.list(request.getHeaders("Idempotency-Key"));if(values.size()!=1||values.getFirst().isBlank()||values.getFirst().length()>100)throw ApiValues.invalid();return ApiValues.idempotencyKey(values.getFirst());}
 private static void noQuery(HttpServletRequest request){if(!request.getParameterMap().isEmpty())throw ApiValues.invalid();}
 private static JsonNode exact(JsonNode body,Set<String> required,Set<String> optional){Set<String> all=new HashSet<>(required);all.addAll(optional);if(body==null||!body.isObject()||!body.propertyNames().containsAll(required)||!all.containsAll(body.propertyNames()))throw ApiValues.invalid();return body;}
 private static String text(JsonNode body,String name){if(!body.path(name).isString())throw ApiValues.invalid();return body.path(name).asString();}
 private PrivateWorkload.Proof proof(String api,HttpServletRequest request){noQuery(request);var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()||!(auth.getPrincipal() instanceof PrivateWorkload.Proof proof))throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!api.equals(proof.route().api())||!"experience".equals(proof.route().owner()))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return proof;}
 private static long ifMatch(HttpServletRequest request){var headers=Collections.list(request.getHeaders("If-Match"));if(headers.size()!=1||!headers.getFirst().matches("\"(0|[1-9][0-9]{0,18})\""))throw ApiValues.invalid();try{return Long.parseLong(headers.getFirst().substring(1,headers.getFirst().length()-1));}catch(Exception failure){throw ApiValues.invalid();}}
 @PostMapping(value="/api/v1/newsletter-subscriptions",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<NewsletterService.Accepted> subscribe(HttpServletRequest request,@RequestBody JsonNode body){noQuery(request);exact(body,Set.of("email","policyVersion","antiSpamToken"),Set.of());var result=newsletter.subscribe(new NewsletterService.Request(text(body,"email"),text(body,"policyVersion"),text(body,"antiSpamToken")),key(request),correlation());return ResponseEntity.status(202).header("Cache-Control","no-store").body(result);}
 @PostMapping(value="/api/v1/newsletter-subscriptions/confirmation",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<NewsletterService.Confirmation> confirm(HttpServletRequest request,@RequestBody JsonNode body){noQuery(request);exact(body,Set.of("token"),Set.of());var result=newsletter.confirm(text(body,"token"),key(request),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").body(result);}
 @PostMapping(value="/api/v1/unsubscribe",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<NewsletterService.Unsubscribed> unsubscribe(HttpServletRequest request,@RequestBody JsonNode body){noQuery(request);exact(body,Set.of("token"),Set.of());var result=newsletter.unsubscribe(text(body,"token"),key(request),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").body(result);}
 @PutMapping(value="/api/v1/me/consents",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<NewsletterService.Consent> setConsent(HttpServletRequest request,@RequestBody JsonNode body){var p=proof("API-102",request);exact(body,Set.of("channel","purpose","granted","policyVersion"),Set.of("destinationId"));if(!body.path("granted").isBoolean())throw ApiValues.invalid();UUID destination=body.has("destinationId")&&!body.path("destinationId").isNull()?ApiValues.uuid(text(body,"destinationId")):null;var input=new NewsletterService.SetConsentInput(destination,text(body,"channel"),text(body,"purpose"),body.path("granted").asBoolean(),text(body,"policyVersion"));String key=key(request);long version=ifMatch(request);NewsletterService.Consent result;if("EMAIL".equals(input.channel()))result=newsletter.setEmailConsent(p,input,version,key,correlation());else{PhoneConsent service=phone.getIfAvailable();if(service==null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);result=service.setConsent(p.actor(),input.destinationId(),input.channel(),input.purpose(),input.granted(),input.policyVersion(),version,key,correlation());}return ResponseEntity.ok().header("Cache-Control","no-store").eTag(Long.toString(version+1)).body(result);}
 @PostMapping(value="/internal/v1/newsletter-subscriptions/{id}/notification-context",consumes=MediaType.APPLICATION_JSON_VALUE,produces=MediaType.APPLICATION_JSON_VALUE) public ResponseEntity<NewsletterService.Context> context(HttpServletRequest request,@PathVariable String id,@RequestBody JsonNode body){var p=proof("API-158",request);exact(body,Set.of("jobId"),Set.of());var result=newsletter.context(p,ApiValues.uuid(id),ApiValues.uuid(text(body,"jobId")),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").body(result);}
}
